Q: Cancel request in dart A: <blockquote>
<blockquote>
<p>I want to know is it possible to cancel upload/download request without closing client client.close?</p>
</blockquote>
</blockquote>
<p>Yes, of course.<br />
This is possible if needed.</p>
<p>Sequence of actions:</p>
<ul>
<li>Send request</li>
<li>Await response</li>
<li>Get the response from the request</li>
<li>Get the stream from the response</li>
<li>Listen to the stream</li>
</ul>
<p>After completing these steps, you can instantly unsubscribe from the stream and everything will work fine.</p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:http/http.dart';
import 'package:multitasking/misc/progress.dart';
import 'package:multitasking/multitasking.dart';

Future&lt;void&gt; main() async {
  final cts = CancellationTokenSource();
  final token = cts.token;

  // User request to cancel
  Timer(Duration(seconds: 3), () {
    print('Canceling...');
    cts.cancel();
  });

  int? percent;
  final progress = Progress(((int count, int total) report) {
    final (count, total) = report;
    final newPercent = total == 0 ? 0 : count * 100 ~/ total;
    if (percent != newPercent) {
      percent = newPercent;
      print('$percent% ${count.mb} MB of ${total.mb} MB');
    }
  });

  final uri = Uri.parse(
      'https://storage.googleapis.com/dart-archive/channels/stable/release/3.0.0/sdk/dartsdk-windows-x64-release.zip');

  final client = Client();
  final request = Request('GET', uri);
  final response = await client.send(request);
  final statusCode = response.statusCode;
  if (statusCode != 200) {
    throw Exception('Http error ($statusCode)');
  }

  final contentLength = response.contentLength;
  var bytes = 0;
  final stream = response.stream;
  var isCanceled = false;
  try {
    await for (final event
        in stream.asCancelable(token, throwIfCanceled: true)) {
      bytes += event.length;
      progress.report((bytes, contentLength ?? 0));
    }
  } on TaskCanceledException {
    isCanceled = true;
  }

  if (isCanceled) {
    print('Canceled');
  }
}

extension on int {
  String get mb =&gt; (this * 1.0 / (1024 * 1024)).toStringAsFixed(2);
}

</code></pre>
<p>Result:</p>
<pre class="lang-none prettyprint-override"><code>0% 0.00 MB of 201.13 MB
1% 2.02 MB of 201.13 MB
2% 4.02 MB of 201.13 MB
3% 6.04 MB of 201.13 MB
4% 8.05 MB of 201.13 MB
Canceling...
Canceled

Exited.
</code></pre>
